outlook365:send-mail.outlook365:message:
#[%dw 2.0
output application/json
var error = vars.vErrorMsg default {}
---
{
  message: {
    subject: "Error in Mulesoft",
    body: {
      contentType: "HTML",
      content: 
        "<p>Hi Team,</p>" ++
        "<p>This is to inform you that an error occurred in the Mulesoft API for the PDF: <b>" ++ (vars.filename default "") ++ "</b></p>" ++
        "<table border='1' cellpadding='5' cellspacing='0' style='border-collapse: collapse;'>"
          ++ "<tr><th>Field</th><th>Value</th></tr>" ++
          "<tr><td>Info</td><td>" ++ (error.Info default "-") ++ "</td></tr>" ++
          "<tr><td>PO Name</td><td>" ++ (error.'Pdf Name' default "-") ++ "</td></tr>" ++
          "<tr><td>Inventory Date</td><td>" ++ (error.'Date' default "-") ++ "</td></tr>" ++
          "<tr><td>Error Type</td><td>" ++ (error.ErrorType default "-") ++ "</td></tr>" ++
          "<tr><td>Error Message</td><td>" ++ (error.ErrorMessage default "-") ++ "</td></tr>" ++
          "<tr><td>Flow Name</td><td>" ++ (error.'Flow Name' default "-") ++ "</td></tr>" ++
          "<tr><td>Timestamp</td><td>" ++ (error.Timestamp default "-") ++ "</td></tr>" ++
        "</table>" ++
        "<p>Thank you</p>"
    },
    toRecipients: p('mail.to') splitBy "," map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    },
    ccRecipients: p('mail.cc') splitBy "," map (email) -> {
      emailAddress: {
        address: trim(email)
      }
    }},
  saveToSentItems: "false"
}]
